async function chooseFolder(id='root',more=false){if(!driveState.connected){await connection();if(!driveState.connected)return dialog===destinationDialog?destinationSettings():scannerSettings();}status('Opening Drive folders…');const r=await api('folders',{parent:id,...(more?{pageToken:folders.next}:{})});folders={parent:r.parent,items:more?[...folders.items,...r.files]:r.files,next:r.nextPageToken};open('Choose Google Drive folder',`<p class="scan-path">${esc(driveState.email)}<br>${esc(r.parent.name)}</p><div class="scan-actions">${btn('folder-root','My Drive')}${r.parent.parents?.length?btn('folder-up','Up'):''}${btn('folder-new','New folder')}${r.parent.capabilities?.canRename?btn('folder-rename','Rename this folder'):''}</div><label>Paste folder link or ID<input id="folderLink" placeholder="https://drive.google.com/drive/folders/…"></label>${btn('folder-link','Open link')}<div>${folders.items.map(f=>`<div class="scan-folder"><button class="scan-action" data-scan="folder-open" data-folder="${f.id}">📁 ${esc(f.name)}</button></div>`).join('')||'<p>No subfolders here.</p>'}</div>${folders.next?btn('folder-more','More folders'):''}<div class="scan-actions">${r.parent.capabilities?.canAddChildren?btn('folder-select','Use this folder','primary'):'<small>This folder is read-only.</small>'}</div>`);status('Choose where the PDF will be uploaded.');}
